/*
 * Stale-asset recovery.
 *
 * Every deploy renames the hashed bundle files in /assets/ and deletes the old ones. A page served from a
 * CDN or browser cache that was generated by the PREVIOUS deploy still points at the deleted files, so its
 * script / stylesheet requests return 404 and the page renders unstyled or blank.
 *
 * This file is NOT hashed, so it is always current. If a /assets/ script or stylesheet fails to load,
 * reload the page ONCE with a cache-busting query so the CDN is forced to return the fresh HTML. The query is
 * removed again right after the reload, and the canonical URL never contains it.
 */
(function () {
  var KEY = 'egt-asset-recovery';
  var PARAM = '_r';

  // Clean the cache-busting parameter after a recovery reload.
  try {
    var url = new URL(window.location.href);
    if (url.searchParams.has(PARAM)) {
      url.searchParams.delete(PARAM);
      window.history.replaceState(null, '', url.pathname + url.search + url.hash);
    }
  } catch (e) { /* ignore */ }

  window.addEventListener(
    'error',
    function (event) {
      var el = event && event.target;
      if (!el || (el.tagName !== 'SCRIPT' && el.tagName !== 'LINK')) return;
      var src = el.src || el.href || '';
      if (src.indexOf('/assets/') === -1) return;
      try {
        if (window.sessionStorage.getItem(KEY)) return; // only one attempt per tab session
        window.sessionStorage.setItem(KEY, String(Date.now()));
      } catch (e) {
        return; // storage unavailable: do not risk a reload loop
      }
      var next = new URL(window.location.href);
      next.searchParams.set(PARAM, String(Date.now()));
      window.location.replace(next.toString());
    },
    true
  );
})();
